#!/usr/bin/env bash
# One-time setup: PKI, negative-test certificates and .env with random secrets.
# Then: docker compose up -d --build && ./scripts/enroll.sh --bootstrap-admin
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

command -v openssl >/dev/null || { echo "openssl is required" >&2; exit 1; }
command -v docker >/dev/null || { echo "docker is required" >&2; exit 1; }

bash pki/init-pki.sh
bash pki/make-test-certs.sh

if [[ ! -f .env ]]; then
  umask 077
  cat > .env <<EOF
# Generated by scripts/setup.sh - never commit this file.
POSTGRES_PASSWORD=$(openssl rand -hex 24)
PROXY_SHARED_SECRET=$(openssl rand -hex 32)
BOOTSTRAP_ADMIN_TOKEN=$(openssl rand -hex 32)
EOF
  echo "[setup] .env created"
else
  echo "[setup] .env already exists, kept"
fi

echo
echo "Next steps:"
echo "  docker compose up -d --build"
echo "  ./scripts/enroll.sh --bootstrap-admin        # enrols the 'admin' certificate"
